sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amount;
uniform float strength;
uniform float black;
uniform float angle;
uniform float phase;
float4 inks(float2 at) {
    half4 c = image.eval(at);
    float3 rgb = c.a > 0.0 ? float3(c.rgb) / float(c.a) : float3(1.0);
    float3 cmy = 1.0 - rgb;
    float k = black * min(cmy.x, min(cmy.y, cmy.z));
    return float4((cmy - k) / max(1.0 - k, 0.0001), k);
}
float screenDot(float2 coord, float turn, int channel) {
    float cell = size.x / max(amount, 0.5);
    float a = radians(angle + turn);
    float cs = cos(a);
    float sn = sin(a);
    float2 o = size * 0.5;
    float2 p = coord - o;
    p = float2(cs * p.x + sn * p.y, -sn * p.x + cs * p.y) / cell;
    float row = floor(p.y);
    p.x -= phase * row;
    float2 m = float2(floor(p.x) + 0.5, row + 0.5);
    float2 back = float2(m.x + phase * row, m.y) * cell;
    float4 ink = inks(o + float2(cs * back.x - sn * back.y, sn * back.x + cs * back.y));
    float v = channel == 0 ? ink.x : channel == 1 ? ink.y : channel == 2 ? ink.z : ink.w;
    float s = clamp(strength, 0.001, 0.999);
    float r = 0.7071 * sqrt(pow(clamp(v, 0.0, 1.0), (1.0 - s) / s)) * cell;
    return clamp(r - length(p - m) * cell + 0.5, 0.0, 1.0);
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    float c = screenDot(coord, -30.0, 0);
    float m = screenDot(coord, 30.0, 1);
    float y = screenDot(coord, -45.0, 2);
    float k = black > 0.0 ? screenDot(coord, 0.0, 3) : 0.0;
    float3 rgb = (1.0 - float3(c, m, y)) * (1.0 - k);
    return half4(half3(rgb) * src.a, src.a);
}
